pub fn arrhenius(
    pre_exponential: f64,
    temperature_exponent: f64,
    activation_energy: f64,
    temperature_k: f64,
) -> f64 {
    let temperature_k = temperature_k.max(1.0);
    pre_exponential
        * temperature_k.powf(temperature_exponent)
